<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();
$db=saas_db();$user=saas_current_user();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$name=trim((string)$_POST['name']);$email=trim((string)$_POST['email']);$username=trim((string)$_POST['username']);if($name==='')throw new RuntimeException('Name is required.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Invalid email.');if($username!==''&&!preg_match('/^[A-Za-z0-9._-]{3,100}$/',$username))throw new RuntimeException('Username may use letters, numbers, dot, underscore and hyphen.');$q=$db->prepare("SELECT id FROM users WHERE (email=? OR username=?) AND id<>? LIMIT 1");$q->execute([$email?:null,$username?:null,saas_user_id()]);if($q->fetch())throw new RuntimeException('Email or username is already in use.');$q=$db->prepare('UPDATE users SET name=?,email=?,username=? WHERE id=?');$q->execute([$name,$email?:null,$username?:null,saas_user_id()]);$ok='Account settings saved.';$user=saas_current_user();}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account settings — GoTM</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font-family:Inter,Arial,sans-serif;color:#172033}.box{max-width:700px;margin:40px auto;background:#fff;padding:28px;border-radius:18px;box-shadow:0 8px 30px #0001}label{display:block;font-size:13px;font-weight:700;margin:14px 0}input{width:100%;padding:11px;border:1px solid #d0d5dd;border-radius:9px;font:inherit;margin-top:6px}button,a{padding:10px 14px;border-radius:9px;font-weight:800}button{border:0;background:#155eef;color:#fff;cursor:pointer}.actions{display:flex;gap:8px;margin-top:20px}.actions a{border:1px solid #d0d5dd;color:#172033}.msg{padding:11px;border-radius:9px;margin-bottom:14px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}.muted{color:#667085;font-size:13px}</style></head><body><main class="box"><p><a href="tours.php">← Back to tours</a></p><h1>Account settings</h1><p class="muted">Update your GoTM user profile. Organization and tour access are managed separately.</p><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><label>Name<input name="name" value="<?=saas_h($user['name']??'')?>" required></label><label>Username<input name="username" value="<?=saas_h($user['username']??'')?>"></label><label>Email<input type="email" name="email" value="<?=saas_h($user['email']??'')?>"></label><div class="actions"><button>Save changes</button><a href="tours.php">Cancel</a></div></form></main></body></html>